const $=id=>document.getElementById(id);const data=JSON.parse($('bank').textContent), P=data.practice,D=data.diagnostic;let page=0;const size=12;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function fmt(s){const frac=(a,b)=>'<span class="fraction"><span>'+esc(a)+'</span><span>'+esc(b)+'</span></span>';let raw=String(s), result='', last=0;const pattern=/\\\(\\frac\{([^{}]+)\}\{([^{}]+)\}\\\)|(?<![\w./])((?:\d+(?:\.\d+)?|[a-zA-Z]))\s*\/\s*((?:\d+(?:\.\d+)?|[a-zA-Z]))(?![\w/]|\.\d)/g;for(const m of raw.matchAll(pattern)){if(!m[1]&&!/\d/.test(m[3]+m[4]))continue;if(!m[1]&&['m/s','L/min','km/h'].includes(m[0]))continue;result+=esc(raw.slice(last,m.index))+frac(m[1]??m[3],m[2]??m[4]);last=m.index+m[0].length}return result+esc(raw.slice(last))};const skills=[...new Set(P.map(q=>q.skill))].sort();for(const s of skills)$('skill').add(new Option(s,s));function tab(t){for(const n of ['practice','diagnostic','mini','visual']){$(n).hidden=n!==t;$('tab-'+n).setAttribute('aria-selected',String(n===t))}}document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>tab(x.dataset.tab));function render(){const list=P.filter(q=>(!$('skill').value||q.skill===$('skill').value)&&(!$('difficulty').value||q.difficulty===$('difficulty').value));const max=Math.max(0,Math.ceil(list.length/size)-1);page=Math.min(page,max);$('count').textContent=list.length+' questions · Page '+(page+1)+' of '+(max+1);$('questions').innerHTML=list.slice(page*size,(page+1)*size).map(q=>`<article><small>${esc(q.skill)} · ${esc(q.difficulty)}</small><p>${fmt(q.question)}</p>${diagrams[q.id]||""}<details><summary>Show answer and worked solution</summary><p><strong>${fmt(q.answer)}</strong></p><p>${fmt(q.solution)}</p>${solutionDiagrams[q.id]||''}</details></article>`).join('')||'<p>No questions match these filters.</p>';$('prev').disabled=page===0;$('next').disabled=page===max}for(const id of ['skill','difficulty'])$(id).onchange=()=>{page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};let di=0, responses=[], finished=false;
function diagnostic(){di=0;responses=Array(D.length).fill(null);finished=false;$('results').hidden=true;drawDiagnostic()}
function drawDiagnostic(){const q=D[di];$('test').innerHTML=`<article><p>Question ${di+1} of ${D.length} · ${responses.filter(x=>x!==null).length} answered</p><div class="progress"><div style="width:${100*(di+1)/D.length}%"></div></div><fieldset><legend class="qtitle">${fmt(q.question)}</legend>${diagrams[q.id]||''}${q.options.map((o,j)=>`<label class="option"><input type="radio" name="current" value="${j}" ${responses[di]===j?'checked':''} ${finished?'disabled':''}> <span>${String.fromCharCode(65+j)}. ${fmt(o)}</span></label>`).join('')}</fieldset>${finished?`<div class="solution">${responses[di]===q.correctIndex?'Correct':'Correct answer: '+fmt(q.answer)}<p>${fmt(q.solution)}</p>${solutionDiagrams[q.id]||''}</div>`:''}</article>`;$('test').querySelectorAll('input').forEach(el=>el.onchange=()=>{responses[di]=Number(el.value);drawDiagnostic()});$('dprev').disabled=di===0;$('dnext').disabled=di===D.length-1;$('mark').disabled=finished;}
$('dprev').onclick=()=>{if(di>0){di--;drawDiagnostic()}};$('dnext').onclick=()=>{if(di<D.length-1){di++;drawDiagnostic()}};$('reset').onclick=diagnostic;
$('mark').onclick=()=>{if(responses.includes(null)&&!confirm('Some questions are unanswered. Finish anyway?'))return;finished=true;let correct=0;const groups=new Map();D.forEach((q,i)=>{if(responses[i]===q.correctIndex)correct++;else{const s=q.practiceSkill||q.skill;groups.set(s,(groups.get(s)||0)+1)}});$('results').hidden=false;$('results').innerHTML=`<h3>${correct} / ${D.length} correct (${Math.round(100*correct/D.length)}%)</h3><p>Use Previous and Next to review answers.</p><h4>Recommended practice</h4>`;for(const [s,n] of groups){const el=document.createElement('button');el.textContent=s+' ('+n+' to review)';el.onclick=()=>{$('skill').value=skills.includes(s)?s:'';$('difficulty').value='';page=0;render();tab('practice')};$('results').append(el)}if(!groups.size)$('results').append('All diagnostic questions correct.');di=0;drawDiagnostic();$('results').scrollIntoView({block:'start'})};
for(const s of skills)$('mini-skill').add(new Option(s,s));let mini=[],mi=0,marks=[],revealed=[];function drawMini(){const b=$('mini-body');if(mi===mini.length){b.innerHTML=`<h3>Mini-test complete</h3><p>${marks.filter(Boolean).length} / ${mini.length} self-marked correct.</p><p>Generate another test to practise again.</p>`;return}const q=mini[mi];b.innerHTML=`<article><p>Question ${mi+1} of ${mini.length} · ${esc(q.difficulty)}</p><p class="qtitle">${fmt(q.question)}</p>${diagrams[q.id]||''}<label>Your working<textarea id="mini-work" rows="3"></textarea></label><p><button id="mini-reveal">Reveal answer and solution</button></p><div id="mini-solution" ${revealed[mi]?'':'hidden'}><div class="solution"><strong>${fmt(q.answer)}</strong><p>${fmt(q.solution)}</p>${solutionDiagrams[q.id]||''}</div><p>How did you go?</p><button id="mini-yes">Correct</button> <button id="mini-no">Needs practice</button></div></article>`;$('mini-reveal').onclick=()=>{revealed[mi]=true;$('mini-solution').hidden=false};for(const [id,val] of [['mini-yes',true],['mini-no',false]])$(id).onclick=()=>{marks.push(val);mi++;drawMini()}}
$('mini-start').onclick=()=>{const pool=P.filter(q=>(!$('mini-skill').value||q.skill===$('mini-skill').value)&&(!$('mini-level').value||q.difficulty===$('mini-level').value));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}mini=pool.slice(0,Number($('mini-count').value));mi=0;marks=[];revealed=[];if(!mini.length){$('mini-body').textContent='No questions match these filters.';return}drawMini()};render();diagnostic();tab('diagnostic');
